import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'archived' | 'overrun';

interface Project {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
}

const STATUSES: Array<{ value: ProjectStatus; label: string; tone: 'success' | 'warning' | 'default' | 'danger' }> = [
  { value: 'active', label: 'Активен', tone: 'success' },
  { value: 'paused', label: 'Приостановлен', tone: 'warning' },
  { value: 'archived', label: 'В архиве', tone: 'default' },
  { value: 'overrun', label: 'Перерасход', tone: 'danger' },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel({ projects }: { projects: Project[] }) {
  const [selected, setSelected] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setSelected((current) =>
      current.includes(status) ? current.filter((item) => item !== status) : [...current, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setSelected([]);
    setPage(1);
  };

  const filtered = useMemo(
    () => (selected.length === 0 ? projects : projects.filter((project) => selected.includes(project.status))),
    [projects, selected],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  return (
    <section style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {STATUSES.map((status) => {
          const isActive = selected.includes(status.value);
          return (
            <JxChip
              key={status.value}
              active={isActive}
              removable={isActive}
              onRemove={() => toggleStatus(status.value)}
              onClick={() => toggleStatus(status.value)}
            >
              {status.label}
            </JxChip>
          );
        })}
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Ничего не нашлось"
          message="Под выбранные статусы не подходит ни один проект."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul style={{ listStyle: 'none', margin: 0, padding: 0, display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {visible.map((project) => {
              const status = STATUSES.find((item) => item.value === project.status);
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 16px',
                    background: 'var(--jx-surface)',
                    border: '1px solid var(--jx-border)',
                    borderRadius: 'var(--jx-r)',
                  }}
                >
                  <span style={{ flex: 1, color: 'var(--jx-text)', fontFamily: 'var(--jx-font-sans)' }}>
                    {project.name}
                  </span>
                  <JxProgressCircle value={project.quota} showValue />
                  <JxBadge tone={status?.tone ?? 'default'}>{status?.label ?? project.status}</JxBadge>
                </li>
              );
            })}
          </ul>

          {pageCount > 1 && <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />}
        </>
      )}
    </section>
  );
}

